def require_no_device_assignments(apps, schema_editor):
    """Stop the upgrade, naming what to remove, while Policies, NAT Policies or Zones use Devices or Dynamic Groups.

    Policies and NAT Policies are now assigned to Firewalls, HA Groups and Firewall Groups, and Zones are bound to
    them. There is no safe way to choose those for the old Device, Dynamic Group and Virtual Machine assignments.
    """
    found = []
    for model_name, policy_field, target_field, label in (
        ("PolicyDeviceM2M", "policy", "device", "Policy assigned to Device"),
        ("PolicyDynamicGroupM2M", "policy", "dynamic_group", "Policy assigned to Dynamic Group"),
        ("NATPolicyDeviceM2M", "nat_policy", "device", "NAT Policy assigned to Device"),
        ("NATPolicyDynamicGroupM2M", "nat_policy", "dynamic_group", "NAT Policy assigned to Dynamic Group"),
    ):
        for row in apps.get_model("nautobot_firewall_models", model_name).objects.all():
            found.append(f"{label}: {getattr(row, policy_field).name} -> {getattr(row, target_field).name}")
    Zone = apps.get_model("nautobot_firewall_models", "Zone")
    for zone in Zone.objects.all():
        for target in [*zone.devices.all(), *zone.virtual_machines.all()]:
            found.append(f"Zone bound to Device or Virtual Machine: {zone.name} -> {target.name}")
    if found:
        raise RuntimeError(
            "Policies, NAT Policies and Zones are now assigned to Firewalls, HA Groups and Firewall Groups instead of "
            "Devices, Dynamic Groups and Virtual Machines, and this upgrade does not convert them. Remove the "
            f"{len(found)} {'assignment' if len(found) == 1 else 'assignments'} below, upgrade, then assign the "
            "Policies and Zones to Firewalls again:\n  " + "\n  ".join(found)
        )


